def _calendar_shared_message_bindings(module):
    """Pin complete shared source and every actual local function/method CodeType."""
    source = inspect.getsource(module)
    tree = ast.parse(source, filename=module.__file__)
    if _dump(tree) != CALENDAR_SHARED_MESSAGE_AST:
        raise ValueError('complete admitted shared message source required')
    plain = compile(tree, module.__file__, 'exec', dont_inherit=True)
    bindings = {}
    for node in tree.body:
        if isinstance(node, ast.FunctionDef):
            owner = vars(module).get(node.name)
            if (type(owner) is not FunctionType or owner.__globals__ is not vars(module)
                    or owner.__module__ != module.__name__ or owner.__name__ != node.name
                    or owner.__closure__ is not None or owner.__code__.co_freevars
                    or _code_shape(owner.__code__) != _code_shape(_top_code(plain, node.name))):
                raise ValueError('actual shared message function identity required: ' + node.name)
            bindings[None, node.name] = (owner, owner.__code__)
        elif isinstance(node, ast.ClassDef):
            owner = vars(module).get(node.name)
            if type(owner) is not type or owner.__module__ != module.__name__ or owner.__name__ != node.name:
                raise ValueError('actual shared message class identity required: ' + node.name)
            bindings[node.name, None] = (owner, None)
            class_code = _top_code(plain, node.name)
            for member in node.body:
                if not isinstance(member, ast.FunctionDef):
                    continue
                actual = vars(owner).get(member.name)
                codes = [value for value in class_code.co_consts if type(value) is CodeType
                    and value.co_name == member.name and value.co_qualname == node.name + '.' + member.name]
                if (member.decorator_list or len(codes) != 1 or type(actual) is not FunctionType
                        or actual.__globals__ is not vars(module) or actual.__module__ != module.__name__
                        or actual.__qualname__ != node.name + '.' + member.name
                        or actual.__closure__ is not None or actual.__code__.co_freevars
                        or _code_shape(actual.__code__) != _code_shape(codes[0])):
                    raise ValueError('actual shared message method identity required: ' + member.name)
                bindings[node.name, member.name] = (actual, actual.__code__)
    return bindings


class CalendarScenePrograms(BattleScenePrograms):
    """Original Main454 -> whole monthly cycle on one live Scene/caller stack."""

    def __init__(self, state):
        super().__init__(state)
        self.calendar_modules = {group: importlib.import_module(path) for group, path in MODULE_PATHS.items()}
        self.calendar_originals = {}
        self.calendar_codes = {}
        self.calendar_views = {}
        self.calendar_namespaces = {}
        for group, module in self.calendar_modules.items():
            source = inspect.getsource(module)
            tree = ast.parse(source, filename=module.__file__)
            plain = compile(tree, module.__file__, 'exec', dont_inherit=True)
            complete = dict(EXPECTED_SYNCHRONOUS_SOURCE.get(group, {}))
            complete.update(EXPECTED_SOURCE[group])
            for name, expected in complete.items():
                original = getattr(module, name)
                nodes = [node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == name]
                if len(nodes) != 1 or _dump(nodes[0]) != _dump(ast.parse(expected).body[0]) or type(original) is not FunctionType or (original.__globals__ is not vars(module)) or (original.__module__ != module.__name__) or (original.__name__ != name) or (original.__closure__ is not None) or original.__code__.co_freevars or (_code_shape(_top_code(plain, name)) != _code_shape(original.__code__)):
                    raise ValueError('actual unwrapped complete calendar source owner required: ' + name)
                self.calendar_originals[group, name] = original
                self.calendar_codes[group, name] = original.__code__
            derived = compile(_cooperative_module(group, tree), module.__file__, 'exec', dont_inherit=True)
            namespace = dict(vars(module))
            if '_calendar_program_child' in namespace:
                raise ValueError('calendar private helper must not shadow a business name')
            self.calendar_namespaces[group] = namespace
            for name in VIEW_SPECS[group]:
                original = self.calendar_originals[group, name]
                view = FunctionType(_top_code(derived, name), namespace, name, original.__defaults__, None)
                view.__kwdefaults__ = original.__kwdefaults__
                view.__annotations__ = dict(original.__annotations__)
                if not inspect.isgeneratorfunction(view) or view.__closure__ is not None:
                    raise ValueError('every calendar source view must be a closure-free generator')
                namespace[name] = self.calendar_views[group, name] = view
        self.calendar_namespaces['reuse']['_calendar_program_child'] = self._calendar_child
        self.calendar_namespaces['calendar']['_calendar_call_fields'] = self.calendar_views['reuse', '_calendar_call_fields']
        self.calendar_namespaces['main']['_campaign_call_fields'] = self.views['main', '_campaign_call_fields']
        self.calendar_forward = _forward_scene
        from . import message_scene_steps
        bindings = _calendar_shared_message_bindings(message_scene_steps)
        if message_scene_steps.GameplayMessageScenePrograms is not GameplayMessageScenePrograms:
            raise ValueError('actual imported shared message class required')
        self.calendar_message_module = message_scene_steps
        self.calendar_message_bindings = bindings
        self.message_scene = GameplayMessageScenePrograms(self)

    def require_current(self, state):
        super().require_current(state)
        if hasattr(self, 'calendar_originals'):
            for (group, name), original in self.calendar_originals.items():
                if getattr(self.calendar_modules[group], name) is not original or original.__code__ is not self.calendar_codes[group, name]:
                    raise ValueError('actual calendar source owner was rebound: ' + name)
            if self.calendar_forward is not _forward_scene:
                raise ValueError('actual calendar scene-wait forwarding owner was rebound')
        if hasattr(self, 'calendar_message_bindings'):
            module = self.calendar_message_module
            if module.GameplayMessageScenePrograms is not GameplayMessageScenePrograms:
                raise ValueError('shared message class binding changed during calendar suspension')
            for (class_name, name), (owner, code) in self.calendar_message_bindings.items():
                actual = vars(module).get(name) if class_name is None else vars(module).get(class_name)
                if class_name is not None and name is not None:
                    actual = vars(actual).get(name) if type(actual) is type else None
                if actual is not owner or (code is not None and actual.__code__ is not code):
                    raise ValueError('actual shared message owner changed during calendar suspension')
            if hasattr(self, 'message_scene') and type(self.message_scene) is not GameplayMessageScenePrograms:
                raise ValueError('one exact shared calendar message continuation required')

    def _calendar_child(self, memory, frame, target, token):
        self.require_current(memory.state)
        if (target, token) not in ORIGINAL_CALENDAR_CALLS:
            raise MovementContinuationBoundary(target, frame, 'not an actual whole-calendar CALL/return pair')
        if (target, token) in MESSAGE_PAIRS:
            return (yield from self._scene_message(memory, frame))
        if (target, token) in LOAD_PAIRS:
            return (yield from self.calendar_forward(GameplaySceneLoadSession(memory.state, frame)))
        if (target, token) in REFRESH_PAIRS:
            return (yield from self.calendar_forward(GameplaySceneRefreshSession(memory.state, frame)))
        if target in CALENDAR_ENTRIES:
            return (yield from self.calendar_views['calendar', CALENDAR_ENTRIES[target]](memory, frame))
        return self.calendar_originals['reuse', '_calendar_child_fields'](memory, frame, target)

    def _campaign_child(self, state, frame, target, continuation):
        self.require_current(state)
        if (target, continuation) == (92986, 3240):
            return (yield from self.calendar_views['calendar', 'process_calendar_city_cycle_fields'](SceneRefreshMemory(state), frame))
        return (yield from super()._campaign_child(state, frame, target, continuation))

    def _display_child(self, state, frame, target, continuation):
        self.require_current(state)
        if target == 1108:
            if continuation != 974:
                raise MovementContinuationBoundary(target, frame, 'calendar Main454 requires the actual3CE LONG')
            return (yield from self.calendar_views['main', 'initialize_training_candidate_fields'](state, frame))
        return (yield from super()._display_child(state, frame, target, continuation))

    def main_scene_call(self, state, frame, target, continuation):
        if target != 1108:
            return (yield from super().main_scene_call(state, frame, target, continuation))
        self.require_current(state)
        if self._started or continuation != 974:
            raise ValueError('one actual indexed Main454/3CE invocation required')
        self._started = True
        return (yield from self.views['display', 'display_call_fields'](state, frame, target, continuation))

    def _scene_message(self, memory, frame):
        """Forward the one entered30A74 with real nestedAF48/060C slots alive."""
        self.require_current(memory.state)
        return (yield from self._message_waits(self.message_scene.program(memory, frame)))
